Voici un script de contrôleur à la première personne en GDScript qui peut être appliqué à un nœud KinematicBody dans Godot Engine 3.x :

```gdscript
extends KinematicBody

export var speed := 10.0
export var mouse_sensitivity := 0.2
export var gravity := -9.81

var velocity := Vector3.ZERO
var camera_rot_speed := Vector2()

func _ready():
    $Camera.rotate_object_local(Vector3.UP, -deg2rad($Camera.get_global_transform().basis[2].angle_to(Vector3.FORWARD)))

func _unhandled_input(event):
    if event.is_action_pressed("ui_zoom"):
        $Camera.zoom = clamp($Camera.zoom * 1.1, 0.3, 1.5)

    if event.is_action_released("ui_zoom"):
        $Camera.zoom = clamp($Camera.zoom / 1.1, 0.3, 1.5)

    if event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
        camera_rot_speed = event.relative

func _process(delta):
    $Camera.rotate_object_local(Vector3.UP, -camera_rot_speed.x * mouse_sensitivity)
    $Camera.rotate_object_local(Vector3.RIGHT, camera_rot_speed.y * mouse_sensitivity)
    camera_rot_speed = Vector2()

func _physics_process(delta):
    var direction = Vector3.ZERO

    if Input.is_action_pressed("ui_forward"):
        direction += transform.basis.z
    if Input.is_action_pressed("ui_backward"):
        direction -= transform.basis.z
    if Input.is_action_pressed("ui_left"):
        direction -= transform.basis.x
    if Input.is_action_pressed("ui_right"):
        direction += transform.basis.x

    if direction != Vector3.ZERO:
        direction = direction.normalized()
        velocity = direction * speed

    velocity.y += gravity * delta

    velocity = move_and_slide(velocity, Vector3.UP)
```

Pour appliquer ce script à un nœud KinematicBody dans Godot Engine 4.x, vous devez remplacer le nœud KinematicBody par le nœud `RigidBody` ou `CharacterBody`, selon votre besoin. Pour un contrôleur à la première personne utilisant un nœud `CharacterBody`, vous pouvez utiliser le script suivant :

